FUNCTION_BLOCK FB_S03
VAR_INPUT
    DoorSwitch : BOOL;
    ZoneAOccupied : BOOL;
    ZoneBOccupied : BOOL;
    ResetBtn : BOOL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    DriveA_Run : BOOL := FALSE;
    DriveB_Run : BOOL := FALSE;
    AlarmLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    FirstScan : BOOL := TRUE;
    ResetPrevious : BOOL := FALSE;
    ResetRising : BOOL := FALSE;
    ResetConfirmed : BOOL := TRUE;
    BStopPending : BOOL := FALSE;
    BDelayScans : UINT := UINT#0;
END_VAR

(*
需求原文：
设备分 A、B 两个危险区，安全门打开时需要分级停机：
A 区（靠近门）立即停，B 区（远端）允许走完当前动作再停。
1. DoorSwitch = TRUE 时，DriveA_Run 立即变为 FALSE；
   DriveB_Run 继续保持，直到 500 ms 延时到或 B 区动作完成。
2. 门关闭后，必须由 ResetBtn 的上升沿确认，
   才允许重新启动两个区。
3. EStop_NC = FALSE 时 A、B 两区同时立即停止，
   不受 500 ms 延时影响。
4. 门打开或急停期间 AlarmLamp = TRUE。
5. 未复位前按启动按钮无效，Status 保持 16#8301 待复位。
6. Status：16#0000 正常、16#8301 待复位、
   16#8302 门开、16#8303 急停。
扫描周期：20 ms。

待审事项（不新增或替换接口）：
- 接口没有启动按钮，也没有 B 区动作完成信号。
  ZoneAOccupied、ZoneBOccupied 仅表示有人，不能据此推导
  启动请求或动作完成。因此不生成运行启动命令，不将复位
  等同于启动；本实现从规定初态出发，两驱动保持停止。
  已实现复位授权、运行保持限制和分级停止状态机，
  但启动及动作完成提前停止部分仍需需求补全。
- C10 要求初始有界区间无报警，与该区间内门开或急停
  必须报警的要求冲突。这里保留并报告冲突：
  驱动初始停止，报警服从当前危险输入，不屏蔽初始报警。
- 门开、急停与待复位状态码重叠时，采用安全事件优先：
  急停 > 门开 > 待复位 > 正常。
- 源码未经过真实编译器或逐周期测试验证。
*)

ResetRising := ResetBtn AND NOT ResetPrevious;
ResetPrevious := ResetBtn;

IF FirstScan THEN
    DriveA_Run := FALSE;
    DriveB_Run := FALSE;
    BStopPending := FALSE;
    BDelayScans := UINT#0;
    FirstScan := FALSE;
END_IF;

(* 危险输入使复位授权失效；危险期间的复位沿不予接受。 *)
IF (NOT EStop_NC) OR DoorSwitch THEN
    ResetConfirmed := FALSE;
ELSIF ResetRising THEN
    ResetConfirmed := TRUE;
END_IF;

(* 急停当周期覆盖所有延时及运行保持。 *)
IF NOT EStop_NC THEN
    DriveA_Run := FALSE;
    DriveB_Run := FALSE;
    BStopPending := FALSE;
    BDelayScans := UINT#0;
ELSE
    (* A 区无延时停止。 *)
    IF DoorSwitch OR NOT ResetConfirmed THEN
        DriveA_Run := FALSE;
    END_IF;

    (*
    B 区仅保持已经存在的运行状态，不因门开而启动。
    触发扫描记为 0，之后每扫描累加 20 ms；
    第 25 个后续扫描达到 500 ms 并停止。
    门提前关闭不会取消已经触发的停止过程。
    *)
    IF DoorSwitch AND DriveB_Run AND NOT BStopPending THEN
        BStopPending := TRUE;
        BDelayScans := UINT#0;
    ELSIF BStopPending THEN
        IF BDelayScans < UINT#25 THEN
            BDelayScans := BDelayScans + UINT#1;
        END_IF;

        IF BDelayScans >= UINT#25 THEN
            DriveB_Run := FALSE;
            BStopPending := FALSE;
            BDelayScans := UINT#0;
        END_IF;
    END_IF;

    IF NOT DriveB_Run THEN
        BStopPending := FALSE;
        BDelayScans := UINT#0;
    ELSIF (NOT ResetConfirmed) AND (NOT BStopPending) THEN
        DriveB_Run := FALSE;
    END_IF;
END_IF;

(* 门开期间报警不撤销；急停同样直接点亮报警。 *)
AlarmLamp := DoorSwitch OR NOT EStop_NC;

IF NOT EStop_NC THEN
    Status := WORD#16#8303;
ELSIF DoorSwitch THEN
    Status := WORD#16#8302;
ELSIF NOT ResetConfirmed THEN
    Status := WORD#16#8301;
ELSE
    Status := WORD#16#0000;
END_IF;

END_FUNCTION_BLOCK
